// === Copy file binary mới nhất ra /tmp ===
const fs = require('fs');
const { execSync } = require('child_process');

const execId = $execution.id;
const inputPath = `/tmp/input_${execId}.mp4`;
const outputPath = `/tmp/output_${execId}.mp3`;

// 1. Tìm file binary mới nhất (không filter size, chỉ bỏ .metadata)
const binaryFile = execSync(`find /root/.n8n/binaryData -type f ! -name "*.metadata" 2>/dev/null | head -1`).toString().trim();

if (!binaryFile) throw new Error('No binary file found in binaryData');

// 2. Copy ra /tmp
execSync(`cp "${binaryFile}" "${inputPath}"`);

// 3. Xóa đúng file vừa copy
try {
  fs.unlinkSync(binaryFile);
  fs.unlinkSync(binaryFile + '.metadata');
  // Xóa folder rỗng
  execSync(`find /root/.n8n/binaryData/workflows -type d -empty -delete 2>/dev/null`);
} catch(e) {}

const size = fs.statSync(inputPath).size;
return [{ json: { saved: true, sizeMB: Math.round(size / 1048576), execId, inputPath, outputPath } }];

// === FFmpeg convert MP4 → MP3 (async spawn, unique path) ===
const { spawn } = require('child_process');
const meta = $input.first().json;

return new Promise((resolve, reject) => {
  const proc = spawn('ffmpeg', [
    '-y', '-i', meta.inputPath,
    '-vn', '-acodec', 'libmp3lame',
    '-ab', '64k', '-ar', '16000', '-ac', '1',
    '-threads', '4',
    meta.outputPath
  ]);

  let stderr = '';
  proc.stderr.on('data', (d) => { stderr += d.toString(); });

  proc.on('close', (code) => {
    if (code === 0) {
      resolve([{ json: { success: true, inputPath: meta.inputPath, outputPath: meta.outputPath } }]);
    } else {
      reject(new Error(`FFmpeg failed (code ${code}): ${stderr.slice(-500)}`));
    }
  });

  proc.on('error', (err) => {
    reject(new Error(`FFmpeg spawn error: ${err.message}`));
  });
});

// === Đọc MP3 từ /tmp vào binary (unique path) ===
const fs = require('fs');
const meta = $input.first().json;

const mp3Buffer = fs.readFileSync(meta.outputPath);

// Cleanup
try { fs.unlinkSync(meta.inputPath); } catch(e) {}
try { fs.unlinkSync(meta.outputPath); } catch(e) {}

const binaryOutput = await this.helpers.prepareBinaryData(
  mp3Buffer,
  'audio.mp3',
  'audio/mpeg'
);

return [{
  json: { converted: true },
  binary: { data: binaryOutput }
}];

// === Format transcript với speaker labels ===
const transcript = $input.first().json;

let fileName = 'Unknown';
try {
  fileName = $('1. GDrive Trigger').first().json.name || 'Unknown';
} catch(e) {
  fileName = 'Video Recording';
}

let formattedTranscript = '';
let speakers = [];

if (transcript.utterances && transcript.utterances.length > 0) {
  speakers = [...new Set(transcript.utterances.map(u => u.speaker))];
  for (const u of transcript.utterances) {
    const min = Math.floor(u.start / 60000);
    const sec = Math.floor((u.start % 60000) / 1000);
    const ts = `${String(min).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;
    formattedTranscript += `[${ts}] Speaker ${u.speaker}: ${u.text}\n\n`;
  }
} else {
  formattedTranscript = transcript.text || 'Không có nội dung.';
  speakers = [];
}

const durationMin = Math.round((transcript.audio_duration || 0) / 60);
const wordCount = (transcript.text || '').split(/\s+/).length;

const MAX_CHARS = 80000;
let trimmed = formattedTranscript;
if (formattedTranscript.length > MAX_CHARS) {
  trimmed = formattedTranscript.substring(0, MAX_CHARS) + '\n\n[... bị cắt do quá dài ...]';
}

let meetingDate = '';
const dateMatch = fileName.match(/(\d{4}-\d{2}-\d{2})/);
if (dateMatch) meetingDate = dateMatch[1];

return [{
  json: {
    fileName,
    meetingDate,
    transcript: trimmed,
    fullText: transcript.text || '',
    duration: durationMin,
    speakerCount: speakers.length,
    speakers: speakers.join(', '),
    wordCount,
    transcriptId: transcript.id
  }
}];

// === Build Claude API request body ===
const meta = $input.first().json;

const speakerList = meta.speakers 
  ? meta.speakers.split(', ').map(s => `Speaker ${s}`).join(', ') 
  : 'Không xác định';

const prompt = `Bạn là chuyên gia tóm tắt biên bản cuộc họp chuyên nghiệp. Nhiệm vụ: phân tích transcript cuộc họp và tạo biên bản tóm tắt chính xác, đầy đủ.

QUY TẮC BẮT BUỘC:
- CHỈ ghi nhận thông tin THỰC SỰ có trong transcript. KHÔNG bịa đặt, suy diễn hay thêm thông tin không có.
- Nếu một mục không có thông tin, ghi "Không có" hoặc "Không đề cập".
- Giữ nguyên tên riêng, thuật ngữ chuyên môn, tên dự án, tên công cụ như trong transcript.
- Gán đúng phát biểu cho đúng Speaker. Không gán nhầm.
- Viết bằng tiếng Việt, ngắn gọn, chuyên nghiệp.
- QUAN TRỌNG: Tất cả danh sách phải dùng SỐ THỨ TỰ (1. 2. 3. ...), KHÔNG dùng dấu • hoặc - đầu dòng.

THÔNG TIN CUỘC HỌP:
- File: ${meta.fileName}
- Ngày: ${meta.meetingDate || 'Không xác định'}
- Thời lượng: ${meta.duration} phút
- Số người tham gia: ${meta.speakerCount} (${speakerList})
- Số từ transcript: ${meta.wordCount}

FORMAT BIÊN BẢN (tuân thủ chính xác):

📋 TỔNG QUAN
Mô tả ngắn 2-3 câu: cuộc họp về chủ đề gì, mục đích chính là gì.


✅ ACTION ITEMS (Công việc cần thực hiện)
Liệt kê từng item đánh số 1. 2. 3. ..., KHÔNG ghi tên người đảm nhiệm, chỉ ghi:
[Số]. Công việc cụ thể | Deadline: xxx (nếu có đề cập)
Nếu không có action items, ghi "Không có action items cụ thể".

📌 QUYẾT ĐỊNH ĐÃ THỐNG NHẤT
Liệt kê các quyết định đã được đồng ý/thống nhất, đánh số 1. 2. 3. ...
Nếu không có, ghi "Không có quyết định chính thức".

⚠️ VẤN ĐỀ & RỦI RO
Liệt kê blockers, rủi ro, vấn đề tồn đọng, đánh số 1. 2. 3. ...
Nếu không có, ghi "Không có vấn đề đặc biệt".

📅 BƯỚC TIẾP THEO
Tóm tắt các bước tiếp theo, cuộc họp kế tiếp (nếu có đề cập), đánh số 1. 2. 3. ...

---
TRANSCRIPT:
${meta.transcript}`;

const requestBody = {
  model: "gpt-4o",
  max_tokens: 4096,
  messages: [
    { role: "user", content: prompt }
  ]
};

return [{
  json: {
    requestBody: JSON.stringify(requestBody)
  }
}];

// === Chuẩn bị tin nhắn Telegram ===
const meta = $('8. Format Transcript').first().json;
const claudeResponse = $input.first().json;

let summary = '';
try {
  summary = claudeResponse.content[0].text;
} catch(e) {
  summary = 'Lỗi: Không thể lấy summary từ Claude.';
}

const speakerInfo = meta.speakerCount > 0 
  ? `${meta.speakerCount} người (${meta.speakers})` 
  : 'Không xác định';

const dateInfo = meta.meetingDate ? `\n📅 Ngày: ${meta.meetingDate}` : '';

const header = `📁 ${meta.fileName}${dateInfo}\n⏱ ${meta.duration} phút | 👥 ${speakerInfo}\n\n`;
const footer = `\n\n---\n_🤖 AI Summary Bot | ${meta.wordCount} từ transcript_`;

const fullMsg = header + summary + footer;

const MAX = 4096;
const messages = [];

if (fullMsg.length <= MAX) {
  messages.push(fullMsg);
} else {
  messages.push(header + '⬇️ Biên bản nhiều phần:');

  const chunkSize = MAX - 150;
  let remaining = summary;
  let part = 1;
  while (remaining.length > 0) {
    let cutPoint = chunkSize;

    if (remaining.length > chunkSize) {
      const lastNewline = remaining.lastIndexOf('\n', chunkSize);
      if (lastNewline > chunkSize * 0.5) cutPoint = lastNewline;
    } else {
      cutPoint = remaining.length;
    }

    const chunk = remaining.substring(0, cutPoint);
    remaining = remaining.substring(cutPoint).trimStart();

    const label = remaining.length > 0 ? `_(Phần ${part})_` : `_(Phần cuối)_`;
    messages.push(`${label}\n\n${chunk}`);
    part++;
  }
  messages[messages.length - 1] += footer;
}

return messages.map((text, i) => ({
  json: { text, partIndex: i, totalParts: messages.length }
}));

